let LANG = "en";
function t(text, vars) {
  let out = (TR[LANG] && TR[LANG][text]) || text;
  if (vars) out = out.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
  return out;
}
const isRTL = () => !!(LANGS.find(l => l.id === LANG) || {}).rtl;
const LOCALE = () => (LANGS.find(l => l.id === LANG) || LANGS[0]).locale;
const ARROW = () => (isRTL() ? "←" : "→");
function setLang(id) { LANG = LANGS.some(l => l.id === id) ? id : "en"; }
function detectLang() {
  try {
    const nav = (navigator.languages && navigator.languages[0]) || navigator.language || "en";
    const code = nav.slice(0, 2).toLowerCase();
    return LANGS.some(l => l.id === code) ? code : "en";
  } catch (e) { return "en"; }
}
